select jsonb_build_object(
'schemas',(select jsonb_agg(jsonb_build_object('name',nspname,'acl',nspacl)) from pg_namespace where nspname in ('public','private')),
'tables',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'replica',c.relreplident,'acl',c.relacl,'owner',pg_get_userbyid(c.relowner),'view',case when c.relkind='v' then pg_get_viewdef(c.oid,true) end,'options',c.reloptions,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'type',contype,'def',pg_get_constraintdef(oid,true))) from pg_constraint where conrelid=c.oid),
'indexes',(select jsonb_agg(jsonb_build_object('name',i.relname,'def',pg_get_indexdef(i.oid),'constraint',exists(select from pg_constraint where conindid=i.oid))) from pg_index ix join pg_class i on i.oid=ix.indexrelid where ix.indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('name',tgname,'def',pg_get_triggerdef(oid,true),'enabled',tgenabled)) from pg_trigger where tgrelid=c.oid and not tgisinternal),
'policies',(select jsonb_agg(jsonb_build_object('name',polname,'cmd',polcmd,'permissive',polpermissive,'roles',(select jsonb_agg(case when x=0 then 'public' else pg_get_userbyid(x)::text end order by x) from unnest(polroles) x),'using',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid))) from pg_policy where polrelid=c.oid)) order by n.nspname,c.relname)
from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v')),
'enums',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',t.typname,'labels',(select jsonb_agg(enumlabel order by enumsortorder) from pg_enum where enumtypid=t.oid))) from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname in ('public','private') and t.typtype='e'),
'sequences',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'type',format_type(s.seqtypid,null),'start',s.seqstart,'increment',s.seqincrement,'max',s.seqmax,'min',s.seqmin,'cache',s.seqcache,'cycle',s.seqcycle,'acl',c.relacl)) from pg_sequence s join pg_class c on c.oid=s.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
'auth_triggers',(select jsonb_agg(jsonb_build_object('def',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled)) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='auth' and not t.tgisinternal),
'publications',(select jsonb_agg(jsonb_build_object('publication',p.pubname,'schema',n.nspname,'table',c.relname)) from pg_publication_rel pr join pg_publication p on p.oid=pr.prpubid join pg_class c on c.oid=pr.prrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'size',length(p.prosrc))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prokind='f')
) catalog;